  var kuruldu = false;

  function uygula(doc) {
    if (!doc || !doc.addFileToVFS) return false;
    try {
      doc.addFileToVFS('Roboto-Regular.ttf', NORMAL);
      doc.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
      doc.addFileToVFS('Roboto-Bold.ttf', KALIN);
      doc.addFont('Roboto-Bold.ttf', 'Roboto', 'bold');
      doc.setFont('Roboto', 'normal');
      kuruldu = true;
      return true;
    } catch (e) {
      // Yazı tipi yüklenemezse fiş yine üretilsin — Türkçe bozuk çıkar ama
      // belge hiç oluşmamasından iyidir.
      return false;
    }
  }

  window.ZkPdfFont = { uygula: uygula, hazirMi: function () { return kuruldu; } };
